INSERT INTO public.contests VALUES ('78cdb3c2-ae1d-4676-8193-04d7ce5ce130', 'Bhagavatam Essay Writing Contest', 'An essay writing contest based on the divine teachings and devotional wisdom of Srimad Bhagavatam, the essence of all Vedas. Participants will be evaluated within their age category.', 399, '2026-09-09 23:59:59', true, '/images/contests/bhagavatam.png', '1st place: 10 grams gold medal. 2nd place: VIP Break Darshan to Tirumala Balaji Temple. 3rd place: VIP Break Darshan to Tirumala Balaji Temple. 4th place: ISKCON Life Patron Membership. 5th place: ISKCON Life Patron Membership.', '["Essay must be original and based on the theme of Bhagavatam.", "Only one valid registration per participant per contest.", "Essay must be submitted online before 09/09/2026.", "Any plagiarism or copied content will lead to disqualification.", "Organizers decision in evaluation and prizes will be final.", "Evaluation will be done separately for 0 to 25 years and above 25 years."]', '2026-09-04 23:59:59', '2026-09-19 10:00:00', '["0 to 25 years", "Above 25 years"]', '["One Bhagavatam book", "Choice of home delivery or direct temple delivery or donation", "Free Work Life Balance course - 180 minutes, available after contest completion and prize distribution"]', 'Bhagavatam');
INSERT INTO public.contests VALUES ('5c4c57df-5913-4abe-a0f0-9c42114bc3c0', 'Ramayana Essay Writing Contest', 'An essay writing contest based on the values, teachings, and inspiring episodes of the Ramayana. Participants will be evaluated within their age category.', 399, '2026-09-09 23:59:59', true, '/images/contests/ramayana.png', '1st place: 10 grams gold medal. 2nd place: VIP Break Darshan to Tirumala Balaji Temple. 3rd place: VIP Break Darshan to Tirumala Balaji Temple. 4th place: ISKCON Life Patron Membership. 5th place: ISKCON Life Patron Membership.', '["Essay must be original and based on the theme of Ramayana.", "Only one valid registration per participant per contest.", "Essay must be submitted online before 09/09/2026.", "Any plagiarism or copied content will lead to disqualification.", "Organizers decision in evaluation and prizes will be final.", "Evaluation will be done separately for 0 to 25 years and above 25 years."]', '2026-09-04 23:59:59', '2026-09-19 10:00:00', '["0 to 25 years", "Above 25 years"]', '["One Ramayana book", "Choice of home delivery or direct temple delivery or donation", "Free Work Life Balance course - 180 minutes, available after contest completion and prize distribution"]', 'Ramayana');
INSERT INTO public.contests VALUES ('88973f2f-7dc9-4d77-ac3c-eca710f3f71c', 'Krishna Essay Writing Contest', 'An essay writing contest centered on the life, teachings, and divine pastimes of Lord Krishna. Participants will be evaluated within their age category.', 399, '2026-09-09 23:59:59', true, '/images/contests/krishna.png', '1st place: 10 grams gold medal. 2nd place: VIP Break Darshan to Tirumala Balaji Temple. 3rd place: VIP Break Darshan to Tirumala Balaji Temple. 4th place: ISKCON Life Patron Membership. 5th place: ISKCON Life Patron Membership.', '["Essay must be original and based on the theme of Lord Krishna.", "Only one valid registration per participant per contest.", "Essay must be submitted online before 09/09/2026.", "Any plagiarism or copied content will lead to disqualification.", "Organizers decision in evaluation and prizes will be final.", "Evaluation will be done separately for 0 to 25 years and above 25 years."]', '2026-09-04 23:59:59', '2026-09-19 10:00:00', '["0 to 25 years", "Above 25 years"]', '["One Krishna book", "Choice of home delivery or direct temple delivery or donation", "Free Work Life Balance course - 180 minutes, available after contest completion and prize distribution"]', 'Krishna Book');
INSERT INTO public.contests VALUES ('53414267-620e-464c-92d9-a9dd31a91c42', 'Bhagavad Gita Essay Writing Contest', 'An essay writing contest based on the wisdom and teachings of the Bhagavad Gita. Participants will be evaluated within their age category.', 399, '2026-09-09 23:59:59', true, '/images/contests/bhagavad-gita.png', '1st place: 10 grams gold medal. 2nd place: VIP Break Darshan to Tirumala Balaji Temple. 3rd place: VIP Break Darshan to Tirumala Balaji Temple. 4th place: ISKCON Life Patron Membership. 5th place: ISKCON Life Patron Membership.', '["Essay must be original and based on the theme of Bhagavad Gita.", "Only one valid registration per participant per contest.", "Essay must be submitted online before 09/09/2026.", "Any plagiarism or copied content will lead to disqualification.", "Organizers decision in evaluation and prizes will be final.", "Evaluation will be done separately for 0 to 25 years and above 25 years."]', '2026-09-04 23:59:59', '2026-09-19 10:00:00', '["0 to 25 years", "Above 25 years"]', '["One Bhagavad Gita book", "Choice of home delivery or direct temple delivery or donation", "Free Work Life Balance course - 180 minutes, available after contest completion and prize distribution"]', 'Bhagavad Gita');
